fn is_greater(n: i32, a: Vec<i32>) -> bool {
    // Check each element in the array.
    // As soon as we find an element >= n, we know n is not strictly greater than all elements.
    for &x in &a {
        if n <= x {
            return false;
        }
    }
    // If we never found such an element, n is strictly greater than every element (or the array was empty).
    true
}

